<script setup lang="ts">
import { computed,ref } from 'vue'
import { api } from './api'
import WorkspaceDialog from './WorkspaceDialog.vue'
const open=ref(false),busy=ref(false),error=ref(''),notice=ref(''),state=ref<any>(null),active=ref('concurrency_cases.md'),search=ref(''),selected=ref(''),context=ref(''),contextBase=ref(''),drafts=ref<Record<string,any>>({}),pending=ref('')
const metadata=['分类','来源类型','确认状态','来源','适用环境','关键共享对象','执行上下文','识别线索','检索关键词']
const sections=[['2','代码示例'],['3','发生过程'],['4','为什么容易漏查'],['5','建议怎样排查'],['6','容易误判的地方'],['7','什么证据可以排除风险'],['8','适用范围和仍未知的情况']]
const document=computed(()=>state.value?.documents[active.value]),entries=computed(()=>state.value?.documents['concurrency_cases.md']?.entries||[])
const visible=computed(()=>entries.value.filter((e:any)=>(e.id+' '+e.form.title).toLowerCase().includes(search.value.toLowerCase())))
const current=computed(()=>drafts.value[selected.value]?.form)
const dirtyCases=computed(()=>Object.values<any>(drafts.value).filter(d=>JSON.stringify(d.form)!==d.base).length)
const dirty=computed(()=>dirtyCases.value>0||context.value!==contextBase.value)
const currentDirty=computed(()=>active.value==='review_context.md'?context.value!==contextBase.value:!!current.value&&JSON.stringify(current.value)!==drafts.value[selected.value].base)
function choose(id:string){selected.value=id;notice.value='';if(!drafts.value[id]){const entry=entries.value.find((e:any)=>e.id===id);if(entry)drafts.value[id]={form:JSON.parse(JSON.stringify(entry.form)),base:JSON.stringify(entry.form),editable:entry.editable}}}
function newCase(){if(!drafts.value.new){const form={title:'',metadata:Object.fromEntries(metadata.map(key=>[key,key==='来源类型'?'用户记录':key==='确认状态'?'待核实':''])),sections:Object.fromEntries(Array.from({length:8},(_,i)=>[String(i+1),'']))};drafts.value.new={form,base:'',editable:true}}selected.value='new';active.value='concurrency_cases.md';notice.value='填写名称和问题描述即可，编号和文件格式由程序生成。'}
async function load(){busy.value=true;error.value='';notice.value='';try{state.value=await api('/review-materials');drafts.value={};context.value=state.value.documents['review_context.md'].content||'';contextBase.value=context.value;selected.value='';if(entries.value.length)choose(entries.value[0].id)}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function show(){open.value=true;pending.value='';await load()}
async function save(){if(!state.value||busy.value)return;busy.value=true;error.value='';notice.value='';try{const name=active.value,edited=selected.value,payload=name==='review_context.md'?{name,action:'context',revision:document.value.revision,text:context.value}:{name,action:'case',revision:document.value.revision,case_id:edited==='new'?null:edited,form:current.value};const value=await api('/review-materials','POST',payload);state.value.documents[name]=value.documents[name];if(name==='review_context.md'){context.value=value.documents[name].content||'';contextBase.value=context.value}else{delete drafts.value[edited];choose(value.selected_case_id)}notice.value='已保存到 config 原文件。下次复核使用新内容，已启动和恢复任务继续使用原快照。';pending.value=''}catch(e:any){error.value=e.message}finally{busy.value=false}}
function request(action:string){if(busy.value)return;if(dirty.value){pending.value=action;return}if(action==='close')open.value=false;else load()}
function discard(){const action=pending.value;pending.value='';if(action==='close')open.value=false;else load()}
defineExpose({show})
</script>
<template><section class="review-materials"><button type="button" @click="show">案例库与工程背景</button><WorkspaceDialog v-if="open" title="案例库与工程背景" :error="error" @close="request('close')"><div class="materials-body"><p class="material-scope">只编辑工具 config 中的两份原文件，供所有工程使用；不需要先保存扫描配置。切换工程前请核对背景。</p><div class="section-tabs" role="tablist" aria-label="复核资料分组"><button role="tab" :disabled="busy" :aria-selected="active==='concurrency_cases.md'" @click="active='concurrency_cases.md'">并发案例库</button><button role="tab" :disabled="busy" :aria-selected="active==='review_context.md'" @click="active='review_context.md'">工程背景（可留空）</button><button :disabled="busy" @click="request('reload')">重新读取原文件</button></div><p v-if="notice" role="status" class="banner">{{notice}}</p><div v-if="pending" class="banner warning" role="alert">有未保存的内容，{{pending==='close'?'关闭':'重新读取'}}会放弃这些草稿。<div class="actions"><button @click="pending=''">继续编辑</button><button @click="discard">{{pending==='close'?'放弃草稿并关闭':'放弃草稿并重新读取'}}</button></div></div><p v-if="busy" role="status">正在读取或保存资料…</p><details v-if="document" class="material-source"><summary>文件位置与保存信息 · {{active}}</summary><p>{{document.path}}</p><p>{{document.bytes}} 字节 · {{document.cases!==undefined?document.cases+' 条案例':(document.effective_chars||0)+' 字符有效背景'}} · SHA-256 {{document.sha256||'尚未创建'}}</p><p v-for="warning in document.warnings" class="muted">{{warning}}</p></details><p v-if="document&&!document.available" class="banner error" role="alert">无法读取原文件：{{document.error}}</p><p v-else-if="document&&!document.editable" class="banner warning">当前文件仅可预览。请直接修复 config 原文件的编码或大小后重新读取；本页面不会改写它。</p><template v-else-if="document&&state"><div v-if="active==='concurrency_cases.md'" class="material-workspace"><aside class="case-picker"><label class="sr-only" for="case-search">查找案例</label><input id="case-search" v-model="search" placeholder="搜索名称或编号"><button :disabled="busy" @click="newCase">新增案例</button><p class="muted">共 {{entries.length}} 条，填写后点击保存</p><div class="case-list" aria-label="案例清单"><button v-if="drafts.new" :disabled="busy" :aria-pressed="selected==='new'" @click="selected='new'">{{drafts.new.form.title||'未保存的新案例'}}<small>待保存 · 自动编号</small></button><button v-for="entry in visible" :key="entry.id" :disabled="busy" :aria-pressed="selected===entry.id" @click="choose(entry.id)">{{entry.form.title}}<small>{{entry.id}}{{drafts[entry.id]&&JSON.stringify(drafts[entry.id].form)!==drafts[entry.id].base?' · 未保存':''}}</small></button></div></aside><div class="case-editor"><template v-if="current"><p class="muted">{{selected==='new'?'新案例：保存时自动编号':selected}} · 直接填写文字，不需要写 Markdown 标记。</p><p v-if="!drafts[selected].editable" class="banner warning">原文编号或章节存在歧义，暂不能安全改写。本案例原文保留，可先新增案例。</p><fieldset :disabled="busy||!drafts[selected].editable"><label>案例名称<input v-model="current.title" aria-label="案例名称" maxlength="300" placeholder="例如：中断更新被前台旧值覆盖"></label><label>问题描述<textarea v-model="current.sections['1']" aria-label="问题描述" rows="6" placeholder="描述现象、原因或已经确认的事实。名称和本项填写后即可保存。"></textarea></label><details class="case-metadata"><summary>分类、识别线索与来源（可选）</summary><label v-for="key in metadata" :key="key">{{key}}<textarea v-model="current.metadata[key]" :aria-label="'案例'+key" rows="2" :placeholder="key==='确认状态'?'写明已核实或仍待核实的依据':key==='识别线索'?'填写相关变量、函数、资源或关键字':'没有的信息可以留空'"></textarea></label></details><details v-for="[key,title] in sections" :key="key"><summary>{{title}} · {{current.sections[key]?'已填写':'可选'}}</summary><label>{{title}}<textarea v-model="current.sections[key]" :aria-label="title" :class="{code:key==='2'}" rows="5" :placeholder="key==='2'?'直接粘贴代码，程序会自动加代码块格式':'直接写文字即可'"></textarea></label></details></fieldset></template><p v-else class="muted">选择左侧案例查看，或点击“新增案例”。</p></div></div><div v-else class="context-editor"><label for="review-context">工程背景（可留空）</label><p class="muted">写清真实入口、优先级、DMA、任务和已知约束；原程序会按既有规则核实。留空保存表示不提供额外背景，不影响扫描和复核。</p><textarea id="review-context" v-model="context" :disabled="busy" aria-label="工程背景正文" placeholder="可直接填写工程说明；没有补充背景时留空。无需填写标题或格式标记。" spellcheck="false"></textarea></div></template></div><template #footer><span>{{dirtyCases?dirtyCases+' 份案例草稿未保存；':''}}{{context!==contextBase?'工程背景未保存；':''}}保存前自动备份原文。</span><div class="actions"><button :disabled="busy" @click="request('close')">关闭</button><button class="primary" :disabled="busy||!document?.available||!document?.editable||(active==='concurrency_cases.md'&&(!current||!drafts[selected]?.editable||!current.title.trim()||!current.sections['1'].trim()))" @click="save">{{active==='review_context.md'?'保存工程背景':'保存当前案例'}}</button></div></template></WorkspaceDialog></section></template>
<style scoped>
.review-materials{margin-top:12px}.materials-body{display:flex;flex-direction:column;flex:1;min-height:0;gap:8px}.material-scope{font-size:13px;margin:0}.material-source{font-size:12px;flex-shrink:0}.material-source p{margin:4px 0}.material-workspace{display:grid;grid-template-columns:minmax(190px,28%) minmax(0,1fr);gap:16px;min-height:0;flex:1}.case-picker{display:flex;flex-direction:column;min-height:0;gap:6px}.case-picker input{margin:0}.case-picker p{margin:0;font-size:12px}.case-list{overflow:auto;min-height:0;flex:1}.case-list button{display:block;width:100%;text-align:left;overflow-wrap:anywhere;border:0;border-bottom:1px solid var(--border);padding:8px;min-height:50px}.case-list button[aria-pressed=true]{background:#eaf1ff;box-shadow:inset 3px 0 #245edb}.case-list small{display:block;color:#667894;margin-top:4px}.case-editor{overflow:auto;min-height:0;padding-right:8px}.case-editor fieldset{border:0;padding:0;margin:0;min-width:0}.case-editor label{max-width:none}.case-editor input,.case-editor textarea{width:100%;line-height:1.5}.case-editor details{border-top:1px solid var(--border);padding:8px 0}.case-editor summary{cursor:pointer}.case-editor .code{font-family:Consolas,monospace}.context-editor{display:flex;flex-direction:column;flex:1;min-height:0}.context-editor p{font-size:13px}.context-editor textarea{flex:1;min-height:220px;line-height:1.65;resize:none}.section-tabs{flex-shrink:0}.materials-body>.banner{margin:0;flex-shrink:0}:global(.workspace-dialog:has(.materials-body) .dialog-body){display:flex;flex-direction:column;overflow:hidden}
@media(max-width:700px){.material-workspace{grid-template-columns:180px minmax(0,1fr);gap:8px}.material-scope{font-size:12px}.case-editor{padding-right:0}}
</style>
